  const maxNumbers = args[0][0];
  const free = new Array(maxNumbers).fill(true);
  let freeCount = maxNumbers;
  for (let i = 1; i < operations.length; i++) {
    const result = actual[i];
    if (operations[i] === 'get') {
      if (result === -1) {
        if (freeCount !== 0) return false;
        continue;
      }
      if (!Number.isInteger(result) || result < 0 || result >= maxNumbers || !free[result]) return false;
      free[result] = false;
      freeCount--;
    } else if (operations[i] === 'check') {
      if (result !== free[args[i][0]]) return false;
    } else {
      if (result !== null) return false;
      const number = args[i][0];
      if (!free[number]) {
        free[number] = true;
        freeCount++;
      }
    }
  }
  return true;
}

