function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'PhoneDirectory' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with PhoneDirectory and its maxNumbers.';
  const maxNumbers = args[0][0];
  if (!Number.isInteger(maxNumbers) || maxNumbers < 1 || maxNumbers > 10000) return 'maxNumbers is between 1 and 10^4.';
  if (operations.length - 1 > 20000) return 'At most 2 * 10^4 calls to get, check and release.';
  for (let i = 1; i < operations.length; i++) {
    if (!Array.isArray(args[i])) return 'Each call needs a list of arguments.';
    if (operations[i] === 'get') {
      if (args[i].length !== 0) return 'get takes no arguments.';
      continue;
    }
    if (operations[i] !== 'check' && operations[i] !== 'release') return 'Only get, check and release can follow the constructor.';
    const [number] = args[i];
    if (args[i].length !== 1 || !Number.isInteger(number) || number < 0 || number >= maxNumbers) return `${operations[i]} takes a number from 0 to maxNumbers - 1.`;
  }
  return null;
}

