class PhoneDirectory {
  constructor(maxNumbers) {
    this.isFree = new Array(maxNumbers).fill(true);
    this.queue = [];
    for (let number = 0; number < maxNumbers; number++) {
      this.queue.push(number);
    }
    this.front = 0;
  }

  get() {
    if (this.front === this.queue.length) {
      return -1;
    }
    const number = this.queue[this.front];
    this.front++;
    this.isFree[number] = false;
    return number;
  }

  check(number) {
    return this.isFree[number];
  }

  release(number) {
    if (this.isFree[number]) {
      return;
    }
    this.isFree[number] = true;
    this.queue.push(number);
  }
}

