function generate(rand, size) {
  let maxNumbers;
  if (size === 'large') maxNumbers = rand() < 0.5 ? 10000 : 1 + Math.floor(rand() * 900);
  else maxNumbers = 1 + Math.floor(rand() * 5);
  const calls = size === 'large' ? 499 : Math.floor(rand() * 16);
  const getRate = 0.3 + rand() * 0.4;
  const operations = ['PhoneDirectory'];
  const args = [[maxNumbers]];
  for (let i = 0; i < calls; i++) {
    const r = rand();
    if (r < getRate) {
      operations.push('get');
      args.push([]);
    } else {
      operations.push(r < getRate + (1 - getRate) / 2 ? 'check' : 'release');
      args.push([Math.floor(rand() * maxNumbers)]);
    }
  }
  return [operations, args];
}
